izes if use_heuristic is True\n    if use_heuristic:\n        next_power_of_2_M = next_power_of_2(M)\n        \n        if next_power_of_2_M <= 32:\n            if N < 8192:\n                block_size_m, block_size_n, block_size_k = 64, 64, 256\n            else:\n                block_size_m, block_size_n, block_size_k = 64, 128, 256\n        elif next_power_of_2_M <= 64:\n            block_size_m, block_size_n, block_size_k = 64, 64, 256\n        elif next_power_of_2_M <= 128:\n            block_size_m, block_size_n, block_size_k = 64, 128, 128\n        else:\n            block_size_m, block_size_n, block_size_k = 128, 128, 128\n\n    grid = lambda META: (triton.cdiv(M, META['BLOCK_SIZE_M']) * triton.cdiv(\n        N, META['BLOCK_SIZE_N']), )\n\n    result = torch.empty((M, N), dtype=out_dtype, device=input.device)\n\n    has_scalar = lambda x: x.shape[0] == 1 and x.shape[1] == 1\n\n    block_size_sa = 1 if has_scalar(scale_a) else block_size_m\n    block_size_sb = 1 if has_scalar(scale_b) else block_size_n\n\n    accumulator_dtype = tl.float32 if input.is_floating_point() else tl.int32\n\n    # A = input, B = weight, C = result\n    # A = M x K, B = K x N, C = M x N\n    scaled_mm_kernel[grid](input,\n                           weight,\n                           scale_a,\n                           scale_b,\n                           result,\n                           bias,\n                           M,\n                           N,\n                           K,\n                           input.stride(0),\n                           input.stride(1),\n                           weight.stride(0),\n                           weight.stride(1),\n                           result.stride(0),\n                           result.stride(1),\n                           accumulator_dtype,\n                           BLOCK_SIZE_M=block_size_m,\n                           BLOCK_SIZE_N=block_size_n,\n                           BLOCK_SIZE_K=block_size_k,\n                           BLOCK_SIZE_SCALE_A=block_size_sa,\n                           BLOCK_SIZE_SCALE_B=block_size_sb)\n\n    return result.to(out_dtype)"
